import type { HTMLAttributes, ReactNode, Ref } from 'react';
import { cn } from '../../utils/cn';
import { SkipLink } from '../../ui/visually-hidden';
import { useI18n } from '../../i18n/I18nProvider';
import { printLayoutVariants, type PrintLayoutVariantProps } from './print-layout.variants';

type PageSize = NonNullable<PrintLayoutVariantProps['size']>;
type PageMargin = NonNullable<PrintLayoutVariantProps['margin']>;

const PAGE_SIZE: Record<PageSize, string> = { a4: 'A4', letter: 'letter' };
const PAGE_MARGIN: Record<PageMargin, string> = { narrow: '12mm', normal: '20mm', wide: '28mm' };

export interface PrintLayoutProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Paper size: A4 (210 × 297 mm) or US Letter (8.5 × 11 in). */
  size?: PageSize;
  /** Page margins (12 · 20 · 28 mm), on screen as padding and in print as the `@page` margin. */
  margin?: PageMargin;
  /** Document header: logo, sender, document number. */
  header?: ReactNode;
  /** Document footer: legal line, page note. */
  footer?: ReactNode;
  /** The document body. Use `PageBreak` between pages. */
  children?: ReactNode;
  /** Emit an `@page` rule with the size and margin (one PrintLayout per printed page set). */
  pageRule?: boolean;
  /** Accessible name of the document. */
  'aria-label'?: string;
  mainId?: string;
  skipLinkLabel?: string;
  fullScreen?: boolean;
}

/**
 * Printable document frame (invoice, report, receipt). On screen it is a paper sheet (card surface,
 * border, flat shadow) at A4 or Letter size on a muted backdrop, in the current theme; in print
 * the chrome drops (no backdrop, border, shadow or outer padding) and `@page` sets size and margins.
 * Print with the light theme (ThemeProvider `defaultMode="light"` or `setMode('light')`).
 */
export function PrintLayout({
  size = 'a4',
  margin = 'normal',
  header,
  footer,
  children,
  pageRule = true,
  'aria-label': ariaLabel,
  mainId = 'main',
  skipLinkLabel: skipLinkLabelProp,
  fullScreen = false,
  className,
  ...props
}: PrintLayoutProps) {
  const { t } = useI18n();
  const skipLinkLabel = skipLinkLabelProp ?? t('skip.document');
  const s = printLayoutVariants({ size, margin, fullScreen });
  return (
    <div className={cn(s.root(), className)} {...props}>
      {pageRule && <style>{`@page { size: ${PAGE_SIZE[size]}; margin: ${PAGE_MARGIN[margin]}; }`}</style>}
      <SkipLink targetId={mainId} className={s.skipLink()}>
        {skipLinkLabel}
      </SkipLink>
      <main id={mainId} tabIndex={-1} className={s.main()}>
        <article aria-label={ariaLabel} className={s.sheet()}>
          {header != null && <header className={s.header()}>{header}</header>}
          <div className={s.content()}>{children}</div>
          {footer != null && <footer className={s.footer()}>{footer}</footer>}
        </article>
      </main>
    </div>
  );
}

export interface PageBreakProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'> {
  className?: string;
  /** On-screen marker text (hidden in print). Pass `null` to hide it. */
  label?: ReactNode;
}

/** Forces a new printed page; on screen it shows as a dashed divider. */
export function PageBreak({ className, label: labelProp, ...props }: PageBreakProps) {
  const { t } = useI18n();
  const label = labelProp ?? t('print.pageBreak');
  const s = printLayoutVariants();
  return (
    <div aria-hidden className={cn(s.pageBreak(), className)} {...props}>
      {label != null && <span className={s.pageBreakLabel()}>{label}</span>}
    </div>
  );
}

export { PrintLayout, PageBreak, type PrintLayoutProps, type PageBreakProps } from './PrintLayout';
export { printLayoutVariants, type PrintLayoutVariantProps } from './print-layout.variants';
export { doc as printLayoutDoc } from './PrintLayout.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const printLayoutVariants = tv({
  slots: {
    root: [
      'relative overflow-auto bg-secondary/40 px-4 py-8 font-sans text-foreground sm:px-8',
      'print:h-auto print:min-h-0 print:overflow-visible print:bg-transparent print:p-0',
    ],
    skipLink: 'focus:absolute print:hidden',
    main: 'outline-none',
    sheet: [
      'mx-auto flex flex-col border border-border bg-card text-card-foreground shadow-sm',
      'print:m-0 print:w-auto print:min-h-0 print:max-w-none print:border-0 print:shadow-none',
    ],
    header: 'flex items-start justify-between gap-6 border-b border-border pb-6',
    content: 'flex-1 py-8 text-[13px] leading-relaxed',
    footer: 'border-t border-border pt-4 text-[11px] text-muted-foreground',
    pageBreak: [
      'relative my-10 border-t border-dashed border-border',
      'break-after-page print:my-0 print:border-0',
    ],
    pageBreakLabel: 'absolute -top-2 left-1/2 -translate-x-1/2 bg-card px-2 font-mono text-[10px] tracking-[0.14em] text-muted-foreground uppercase print:hidden',
  },
  variants: {
    size: {
      a4: { sheet: 'w-[210mm] max-w-full min-h-[297mm]' },
      letter: { sheet: 'w-[8.5in] max-w-full min-h-[11in]' },
    },
    margin: {
      narrow: { sheet: 'p-[12mm] print:p-0' },
      normal: { sheet: 'p-[20mm] print:p-0' },
      wide: { sheet: 'p-[28mm] print:p-0' },
    },
    fullScreen: {
      true: { root: 'h-dvh' },
      false: { root: 'h-full min-h-full' },
    },
  },
  defaultVariants: { size: 'a4', margin: 'normal', fullScreen: false },
});

export type PrintLayoutVariantProps = VariantProps<typeof printLayoutVariants>;

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'PrintLayout',
  group: 'Layout',
  status: 'beta',
  description:
    'Printable document frame for invoices, reports and receipts: an A4 or Letter page (`size`) with margins (`margin`), header and footer slots and a `PageBreak` helper. On screen it is a paper sheet (bg-card / text-card-foreground, border, shadow-sm) on a muted backdrop in the current theme; `print:` variants drop the chrome (no backdrop, border, shadow or outer padding) and an `@page` rule sets paper size and margins (`pageRule`). The header and footer print once, at the top and end of the document. The consuming app should print with the light theme (ThemeProvider `defaultMode="light"`, or `setMode(\'light\')` before `window.print()`); no print-only colours are defined.',
  pattern: 'landmark (main) + labelled article',
  keyboard: [['—', 'None: a static document (the skip link still moves focus to it)']],
  tokens: ['card', 'card-foreground', 'secondary', 'border', 'muted-foreground'],
};
